const STOPWORDS = new Set([
  'de', 'da', 'do', 'dos', 'das', 'em', 'no', 'na', 'nos', 'nas',
  'para', 'pra', 'com', 'que', 'e', 'o', 'a', 'os', 'as', 'um',
  'uma', 'eu', 'tu', 'ti', 'te', 'me', 'se', 'ao', 'aos', 'por',
  'meu', 'teu', 'sua', 'seu', 'mais', 'sem', 'ate', 'que', 'ou'
]);

function norm(str = '') {
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['’`]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getSigTokens(str = '') {
  return norm(str)
    .split(' ')
    .filter(t => t.length >= 2 && !STOPWORDS.has(t));
}

