async function verifyCandidate(cand, usedIds) {
  try {
    const res = await fetch(`https://www.youtube.com/results?search_query=${encodeURIComponent(cand.searchQuery)}`, {
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)' }
    });
    const html = await res.text();
    const rawIds = [...html.matchAll(/"videoId":"([a-zA-Z0-9_-]{11})"/g)].map(m => m[1]);
    const uniqueCandidates = [...new Set(rawIds)].slice(0, 6);

    const normTitle = norm(cand.title.replace(/\([^)]*\)/g, ' '));
    const sigTitleTokens = getSigTokens(cand.title.replace(/\([^)]*\)/g, ' '));
    const sigArtistTokens = getSigTokens(cand.artist);

    const verifiedOptions = [];
    for (const vid of uniqueCandidates) {
      if (usedIds.has(vid) || RESERVED_IDS.has(vid)) continue;
      const oe = await fetch(`https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v=${vid}&format=json`);
      if (!oe.ok) continue;
      const j = await oe.json();
      const ytTitle = norm(j.title || '');
      const ytAuthor = norm(j.author_name || '');
      const combined = `${ytTitle} ${ytAuthor}`;

      // Reject Shorts, sermons, podcasts, karaoke, tutorials, full album compilations
      if (/\b(shorts|pregacao|sermao|mensagem|estudo|podcast|karaoke|playback|cifra|aula|react|rev|pastor|pr|melhores|coletanea|dvd completo)\b/.test(combined)) {
        continue;
      }

      // STRICT TITLE MATCH REQUIRED (at least 60% of significant title words present as whole words, or full normalized title contained)
      const ytWords = new Set(ytTitle.split(' '));
      const titleHitCount = sigTitleTokens.filter(t => ytWords.has(t)).length;
      const exactTitleSubstr = normTitle.length >= 4 && ytTitle.includes(normTitle);
      const titleRatio = sigTitleTokens.length > 0 ? titleHitCount / sigTitleTokens.length : 0;
      const hasStrictTitleMatch = exactTitleSubstr || (sigTitleTokens.length === 1 ? titleHitCount === 1 : titleRatio >= 0.6);

      if (!hasStrictTitleMatch) continue;

      const artistHitCount = sigArtistTokens.filter(t => combined.includes(t)).length;
      const isTopic = ytAuthor.includes('topic');

      verifiedOptions.push({
        youtubeId: vid,
        ytTitle: j.title,
        ytAuthor: j.author_name,
        score: (exactTitleSubstr ? 5 : 2) + artistHitCount * 2 + (isTopic ? 0 : 1)
      });
    }

    verifiedOptions.sort((a, b) => b.score - a.score);
    if (verifiedOptions.length > 0) {
      return verifiedOptions[0];
    }
  } catch (e) {
    // ignore network failure
  }
  return null;
}

(async () => {
  const usedIds = new Set(EXISTING_VERIFIED_SONGS.map(s => s.youtubeId));
  const finalCatalog = EXISTING_VERIFIED_SONGS.map(s => ({ ...s }));

  console.log(`Starting with ${finalCatalog.length} pre-verified songs; strictly checking ${CANDIDATE_SONGS.length} new candidates...`);

  for (let i = 0; i < CANDIDATE_SONGS.length; i += 6) {
    const batch = CANDIDATE_SONGS.slice(i, i + 6);
    const results = await Promise.all(batch.map(c => verifyCandidate(c, usedIds)));
    for (let j = 0; j < batch.length; j++) {
      const cand = batch[j];
      const match = results[j];
      if (match && !usedIds.has(match.youtubeId)) {
        usedIds.add(match.youtubeId);
        const { searchQuery, ...rest } = cand;
        finalCatalog.push({
          ...rest,
          youtubeId: match.youtubeId
        });
        console.log(`  [+] ${cand.title} — ${cand.artist} (${match.youtubeId} | "${match.ytTitle}" by ${match.ytAuthor})`);
      } else {
        console.log(`  [-] SKIPPED: ${cand.title} — ${cand.artist}`);
      }
    }
  }

  fs.writeFileSync(outFile, JSON.stringify(finalCatalog, null, 2), 'utf8');
  console.log(`\nSaved ${finalCatalog.length} STRICTLY verified unique songs to ${outFile}`);
})();
